import{_ as d,o as r,c as e,ag as a}from"./chunks/framework.KxDd3USm.js";const p=JSON.parse('{"title":"11.5 信息安全、云计算与 AI 词汇 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"11-专业英语/05-信息安全云计算与AI词汇.md","filePath":"11-专业英语/05-信息安全云计算与AI词汇.md"}'),i={name:"11-专业英语/05-信息安全云计算与AI词汇.md"};function n(o,t,l,s,c,h){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="_11-5-信息安全、云计算与-ai-词汇-★★★" tabindex="-1">11.5 信息安全、云计算与 AI 词汇 ★★★ <a class="header-anchor" href="#_11-5-信息安全、云计算与-ai-词汇-★★★" aria-label="Permalink to &quot;11.5 信息安全、云计算与 AI 词汇 ★★★&quot;">​</a></h1><h3 id="_5-1-信息安全" tabindex="-1">5.1 信息安全 <a class="header-anchor" href="#_5-1-信息安全" aria-label="Permalink to &quot;5.1 信息安全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>识别句</th></tr></thead><tbody><tr><td>confidentiality</td><td>机密性</td><td>prevent unauthorized disclosure</td></tr><tr><td>integrity</td><td>完整性</td><td>prevent/detect unauthorized modification</td></tr><tr><td>availability</td><td>可用性</td><td>accessible when needed</td></tr><tr><td>authentication</td><td>身份认证</td><td>verify identity</td></tr><tr><td>authorization</td><td>授权</td><td>determine permitted actions</td></tr><tr><td>non-repudiation</td><td>不可否认性</td><td>prevent denial of an action</td></tr><tr><td>encryption / decryption</td><td>加密 / 解密</td><td>plaintext ↔ ciphertext</td></tr><tr><td>symmetric / asymmetric</td><td>对称 / 非对称</td><td>shared key / public-private key pair</td></tr><tr><td>hash / digest</td><td>哈希 / 摘要</td><td>fixed-length, one-way</td></tr><tr><td>digital signature</td><td>数字签名</td><td>private key signs, public key verifies</td></tr><tr><td>vulnerability / exploit</td><td>漏洞 / 利用漏洞的手段</td><td></td></tr><tr><td>threat / attack</td><td>威胁 / 攻击</td><td></td></tr><tr><td>intrusion detection</td><td>入侵检测</td><td>monitor suspicious activity</td></tr></tbody></table><p><strong>反例</strong>：authentication 回答“你是谁”，authorization 回答“你能做什么”。已经登录成功只说明通过认证，不代表有权访问所有资源。</p><h3 id="_5-2-云计算" tabindex="-1">5.2 云计算 <a class="header-anchor" href="#_5-2-云计算" aria-label="Permalink to &quot;5.2 云计算&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th></tr></thead><tbody><tr><td>on demand</td><td>按需</td></tr><tr><td>resource pooling</td><td>资源池化</td></tr><tr><td>elasticity</td><td>弹性伸缩，随负载快速增减资源</td></tr><tr><td>scalability</td><td>可伸缩性，处理增长负载的能力</td></tr><tr><td>virtualization</td><td>虚拟化</td></tr><tr><td>virtual machine / container</td><td>虚拟机 / 容器</td></tr><tr><td>infrastructure/platform/software as a service</td><td>IaaS / PaaS / SaaS</td></tr><tr><td>public/private/hybrid cloud</td><td>公有云 / 私有云 / 混合云</td></tr><tr><td>fault tolerance</td><td>容错</td></tr><tr><td>load balancing</td><td>负载均衡</td></tr></tbody></table><p>三种服务模型用“谁管理得更多”来记：</p><ul><li>IaaS：提供基础设施，用户还要管操作系统和应用；</li><li>PaaS：提供运行平台，用户重点管应用和数据；</li><li>SaaS：直接使用应用，提供商管理最多。</li></ul><h3 id="_5-3-ai-与机器学习" tabindex="-1">5.3 AI 与机器学习 <a class="header-anchor" href="#_5-3-ai-与机器学习" aria-label="Permalink to &quot;5.3 AI 与机器学习&quot;">​</a></h3><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>易混点</th></tr></thead><tbody><tr><td>artificial intelligence</td><td>人工智能</td><td>大范围</td></tr><tr><td>machine learning</td><td>机器学习</td><td>从数据中学习模式</td></tr><tr><td>training / inference</td><td>训练 / 推理</td><td>learn parameters / make predictions</td></tr><tr><td>training set / validation set / test set</td><td>训练集 / 验证集 / 测试集</td><td>学习 / 调参 / 最终评估</td></tr><tr><td>feature / label</td><td>特征 / 标签</td><td>input property / target</td></tr><tr><td>supervised learning</td><td>监督学习</td><td>labeled data</td></tr><tr><td>unsupervised learning</td><td>无监督学习</td><td>discover structure without labels</td></tr><tr><td>classification / regression</td><td>分类 / 回归</td><td>离散类别 / 连续数值</td></tr><tr><td>overfitting / underfitting</td><td>过拟合 / 欠拟合</td><td>记住噪声 / 模型过于简单</td></tr><tr><td>generalization</td><td>泛化</td><td>对未见数据的表现</td></tr><tr><td>accuracy / precision / recall</td><td>准确率 / 精确率 / 召回率</td><td>三个指标不可混用</td></tr></tbody></table><p>必背句：A model that performs well on training data but poorly on unseen data is <strong>overfitting</strong>（训练集好、陌生数据差，就是过拟合）。</p><p><strong>应试动作</strong>：安全题先分“身份 authentication / 权限 authorization / 保密 confidentiality / 防篡改 integrity”；云题抓 <code>on-demand, elasticity, service</code>；AI 题抓 <code>training, prediction, unseen data, overfitting</code>。</p><hr>',13)])])}const _=d(i,[["render",n]]);export{p as __pageData,_ as default};
